import Form from 'flarum/common/components/Form';
import app from 'flarum/common/app';
import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import ItemList from 'flarum/common/utils/ItemList';
import Stream from 'flarum/common/utils/Stream';
import Switch from 'flarum/common/components/Switch';
import Select from 'flarum/common/components/Select';
import Group from 'flarum/common/models/Group';
export default class EditQuestionModal extends FormModal {
  oninit(vnode) {
    super.oninit(vnode);
    const question = this.attrs.question;
    this.questionText = Stream(question.question() || '');
    this.answer = Stream(question.answer() || '');
    this.groupId = Stream(question.groupId() || '');
    this.maxUses = Stream(question.maxUses());
    this.activates = Stream(question.activates() || false);
  }
  className() {
    return 'Modal--small EditQuestionModal';
  }
  title() {
    return app.translator.trans('stezkoy-doorquest.admin.modals.edit_question.title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, m(Form, null, this.fields().toArray()));
  }
  fields() {
    const items = new ItemList();
    items.add('question', m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('stezkoy-doorquest.admin.modals.create_question.question.label')), m("textarea", {
      className: "FormControl",
      bidi: this.questionText,
      disabled: this.loading,
      rows: 3
    })), 100);
    items.add('answer', m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('stezkoy-doorquest.admin.modals.create_question.answer.label')), m("input", {
      className: "FormControl",
      bidi: this.answer,
      disabled: this.loading
    })), 90);
    items.add('group', m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('stezkoy-doorquest.admin.modals.create_question.group.label')), m(Select, {
      name: "groupId",
      options: this.getGroupsForInput(),
      value: String(this.groupId()),
      onchange: val => this.groupId(Number(val)),
      disabled: this.loading
    })), 80);
    items.add('maxUses', m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('stezkoy-doorquest.admin.modals.create_question.max_uses.label')), m("input", {
      className: "FormControl",
      name: "maxUses",
      type: "number",
      bidi: this.maxUses,
      disabled: this.loading
    })), 70);
    items.add('activates', m("div", {
      className: "Form-group"
    }, m("label", null, app.translator.trans('stezkoy-doorquest.admin.modals.create_question.activates_user.label')), m(Switch, {
      name: "activates",
      state: this.activates(),
      onchange: checked => this.activates(checked),
      disabled: this.loading
    }, '‎')), 60);
    items.add('submit', m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary",
      type: "submit",
      loading: this.loading
    }, app.translator.trans('stezkoy-doorquest.admin.modals.edit_question.submit_button'))), -10);
    return items;
  }
  getGroupsForInput() {
    let options = {};
    app.store.all('groups').map(group => {
      const groupCasted = group;
      if (groupCasted.id() === Group.GUEST_ID) {
        return;
      }
      options[groupCasted.id()] = groupCasted.nameSingular();
    });
    return options;
  }
  data() {
    return {
      question: this.questionText().trim(),
      answer: this.answer().trim(),
      groupId: Number(this.groupId()),
      maxUses: Number(this.maxUses()),
      activates: this.activates()
    };
  }
  onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    this.attrs.question.save(this.data(), {
      errorHandler: this.onerror.bind(this)
    }).then(this.hide.bind(this)).catch(() => {
      this.loading = false;
    });
  }
}
flarum.reg.add('stezkoy-doorquest', 'admin/components/EditQuestionModal', EditQuestionModal);